} else {
    // Caso raro: ni el INSERT ni la compensacion funcionaron -> queda huerfano.
    // Se deja constancia explicita en los logs de Node-RED para resolver a mano.
    node.warn("COMPENSACION FALLIDA: usuario huerfano en Traccar, userId=" + msg.userId +
        " (HTTP " + msg.statusCode + "). Revisar y eliminar manualmente si corresponde.");
    node.status({ fill: "red", shape: "ring", text: "Compensacion fallo - userId " + msg.userId });
}

// El cliente siempre recibe el error original del INSERT, sin importar
// si la compensacion tuvo exito o no -> la compensacion es transparente.
msg.statusCode = msg._originalError.statusCode;
msg.payload = msg._originalError.payload;
return msg;
